COMMIT:b77c87176
b77c87176 utils: avoid overflowing string buffer in flb_utils_write_str() (#1633)
 src/flb_utils.c | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)
commit b77c871760a2f75330a5a5442c6fd9f5e1bfc59a
Author: Fujimoto Seiji <fujimoto@clear-code.com>

    utils: avoid overflowing string buffer in flb_utils_write_str() (#1633)

diff --git a/src/flb_utils.c b/src/flb_utils.c
index 295110013..fff15b2d9 100644
--- a/src/flb_utils.c
+++ b/src/flb_utils.c
@@ -585,7 +585,7 @@ int flb_utils_write_str(char *buf, int *off, size_t size,
         }
         else if (c >= 0x80 && c <= 0xFFFF) {
             hex_bytes = flb_utf8_len(str + i);
-            if ((available - written) < (2 + hex_bytes)) {
+            if ((available - written) < 6) {
                 return FLB_FALSE;
             }

COMMIT:428180f6a
428180f6a utils: fix buffer overrun on invalid UTF-8 characters
 src/flb_utils.c | 10 ++++++++--
 1 file changed, 8 insertions(+), 2 deletions(-)
commit 428180f6a6dbf9b3bea7d1c1746877b2bc632e94
Author: Fujimoto Seiji <fujimoto@clear-code.com>

    utils: fix buffer overrun on invalid UTF-8 characters

diff --git a/src/flb_utils.c b/src/flb_utils.c
index fff15b2d9..8b59cac51 100644
--- a/src/flb_utils.c
+++ b/src/flb_utils.c
@@ -585,9 +585,12 @@ int flb_utils_write_str(char *buf, int *off, size_t size,
         }
         else if (c >= 0x80 && c <= 0xFFFF) {
             hex_bytes = flb_utf8_len(str + i);
-            if ((available - written) < 6) {
+            if (available - written < 6) {
                 return FLB_FALSE;
             }
+            if (i + hex_bytes > str_len) {
+                break; /* skip truncated UTF-8 */
+            }

             state = FLB_UTF8_ACCEPT;
             codepoint = 0;
@@ -612,9 +615,12 @@ int flb_utils_write_str(char *buf, int *off, size_t size,
         }
         else if (c > 0xFFFF) {
             hex_bytes = flb_utf8_len(str + i);
-            if ((available - written) < (4 + hex_bytes)) {
+            if (available - written < 6) {
                 return FLB_FALSE;
             }
+            if (i + hex_bytes > str_len) {
+                break; /* skip truncated UTF-8 */
+            }

             state = FLB_UTF8_ACCEPT;
             codepoint = 0;
COMMIT:73410b3cd
73410b3cd utils: fix bad handling of utf-8 parsing (oss-fuzz 26304)
 src/flb_utils.c | 9 +++++++++
 1 file changed, 9 insertions(+)
commit 73410b3cd81ac8972160902db7d6f666cad3a7fa
Author: davkor <david@adalogics.com>

    utils: fix bad handling of utf-8 parsing (oss-fuzz 26304)

diff --git a/src/flb_utils.c b/src/flb_utils.c
index 060771507..8f46f025c 100644
--- a/src/flb_utils.c
+++ b/src/flb_utils.c
@@ -647,6 +647,9 @@ int flb_utils_write_str(char *buf, int *off, size_t size,
                 return FLB_FALSE;
             }
             len = snprintf(tmp, sizeof(tmp) - 1, "\\u%.4hhx", (unsigned char) c);
+            if ((available - written) < len) {
+                return FLB_FALSE;
+            }
             encoded_to_buf(p, tmp, len);
             p += len;
         }
@@ -677,6 +680,9 @@ int flb_utils_write_str(char *buf, int *off, size_t size,
             }
             else {
                 len = snprintf(tmp, sizeof(tmp) - 1, "\\u%.4x", codepoint);
+                if ((available - written) < len) {
+                    return FLB_FALSE;
+                }
                 encoded_to_buf(p, tmp, len);
                 p += len;
             }
@@ -708,6 +714,9 @@ int flb_utils_write_str(char *buf, int *off, size_t size,
             }
             else {
                 len = snprintf(tmp, sizeof(tmp) - 1, "\\u%04x", codepoint);
+                if ((available - written) < len) {
+                    return FLB_FALSE;
+                }
                 encoded_to_buf(p, tmp, len);
                 p += len;
             }
